/* ————— Application ————— */
export default function App() {
  const [prenom, setPrenom] = useState(null);
  const [ecran, setEcran] = useState("bienvenue");
  const [mIdx, setMIdx] = useState(0);
  const [prog, setProg] = useState(MODULES.map(() => ({ lecons: false, quiz: null, scen: null })));
  const [points, setPoints] = useState(0);
  const [ratees, setRatees] = useState([]);

  const majProg = (i, maj) => setProg(prog.map((p, j) => (j === i ? { ...p, ...maj } : p)));

  const leconsFinies = () => {
    if (!prog[mIdx].lecons) {
      majProg(mIdx, { lecons: true });
      setPoints(points + MODULES[mIdx].lecons.length * 5);
    }
    setEcran("accueil");
  };

  const finQuiz = (score, manquees) => {
    const deja = prog[mIdx].quiz;
    if (deja === null) setPoints(points + score * 10);
    else if (score > deja) setPoints(points + (score - deja) * 10);
    majProg(mIdx, { quiz: deja === null ? score : Math.max(deja, score) });
    const nouvelles = manquees
      .map((qi) => ({ m: mIdx, q: qi }))
      .filter((n) => !ratees.some((r) => r.m === n.m && r.q === n.q));
    setRatees([...ratees, ...nouvelles]);
    setEcran("accueil");
  };

  const finScenario = (pts) => {
    const deja = prog[mIdx].scen;
    if (deja === null) setPoints(points + pts);
    else if (pts > deja) setPoints(points + (pts - deja));
    majProg(mIdx, { scen: deja === null ? pts : Math.max(deja, pts) });
    setEcran("accueil");
  };

  const reussiteRevision = (item) => setRatees(ratees.filter((r) => !(r.m === item.m && r.q === item.q)));

  return (
    <div style={{ minHeight: "100vh", background: "#0A0A14", display: "flex", justifyContent: "center" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@500;600;700&family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&display=swap');
        * { box-sizing: border-box; margin: 0; }
        .btn:focus-visible { outline: 2px solid ${C.or}; outline-offset: 2px; }
        .btn:hover { opacity: .93; }
        @media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
      `}</style>
      <div style={{ width: "100%", maxWidth: 460, background: C.ivoire, minHeight: "100vh", boxShadow: "0 0 40px rgba(0,0,0,0.4)" }}>
        {ecran === "bienvenue" && <Bienvenue onCommencer={(n) => { setPrenom(n); setEcran("accueil"); }} />}
        {ecran === "accueil" && (
          <Accueil
            prenom={prenom}
            prog={prog}
            points={points}
            ratees={ratees}
            ouvrirModule={(i) => { setMIdx(i); setEcran("module"); }}
            ouvrirRevision={() => setEcran("revision")}
            ouvrirLexique={() => setEcran("lexique")}
            ouvrirAcademie={() => setEcran("academie")}
          />
        )}
        {ecran === "module" && (
          <VueModule
            module={MODULES[mIdx]}
            p={prog[mIdx]}
            onLeconsFinies={leconsFinies}
            allerQuiz={() => setEcran("quiz")}
            allerScenario={() => setEcran("scenario")}
            onRetour={() => setEcran("accueil")}
          />
        )}
        {ecran === "quiz" && <VueQuiz module={MODULES[mIdx]} onFin={finQuiz} onRetour={() => setEcran("module")} />}
        {ecran === "scenario" && <VueScenario module={MODULES[mIdx]} onFin={finScenario} onRetour={() => setEcran("module")} />}
        {ecran === "revision" && <VueRevision ratees={ratees} onReussite={reussiteRevision} onRetour={() => setEcran("accueil")} />}
        {ecran === "lexique" && <VueLexique onRetour={() => setEcran("accueil")} />}
        {ecran === "academie" && <VueAcademie onRetour={() => setEcran("accueil")} />}
      </div>
    </div>
  );
}
